     8	import java.time.LocalDate;
     9	import java.time.format.DateTimeFormatter;
    10	
    11	public class ReservationService {
    12	    private final ReservationRepository reservationRepository = new ReservationRepository();
    13	    private final RoomRepository roomRepository = new RoomRepository();
    14	    private final MessageRepository messageRepository = new MessageRepository();
    15	
    16	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
    17	                                         String guestCpf, LocalDate checkIn, LocalDate checkOut,
    18	                                         int guests, RatePlan ratePlan) throws Exception {
    19	        // Validate room exists
    20	        Room room = roomRepository.findByNumber(roomNumber)
    21	            .orElseThrow(() -> new ApiException("ROOM_NOT_FOUND", "Room not found", 404));
    22	
    23	        // Validate check-out is after check-in
    24	        if (!checkOut.isAfter(checkIn)) {
    25	            throw new ApiException("INVALID_REQUEST", "Check-out must be after check-in", 400);
    26	        }
    27	
    28	        // Validate guests count
    29	        if (guests < 1) {
    30	            throw new ApiException("INVALID_REQUEST", "Must have at least 1 guest", 400);
    31	        }
    32	
    33	        if (guests > room.getCapacity()) {
    34	            throw new ApiException("CAPACITY_EXCEEDED", "Room capacity exceeded", 422);
    35	        }
    36	
    37	        // Check for room availability
    38	        LocalDate current = checkIn;
    39	        while (current.isBefore(checkOut)) {
    40	            var conflicts = reservationRepository.findByRoomAndNight(roomNumber, current);
    41	            if (!conflicts.isEmpty()) {
    42	                throw new ApiException("ROOM_UNAVAILABLE", "Room is unavailable for these dates", 409);
    43	            }
    44	            current = current.plusDays(1);
    45	        }
    46	
    47	        // Calculate pricing
    48	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    49	        double subtotal = SeasonCalculator.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
    50	        double discount = Rounding.round(subtotal * ratePlan.getDiscountPercentage());
    51	        double total = Rounding.round(subtotal - discount);
    52	
    53	        // Create reservation
    54	        Reservation reservation = new Reservation(
    55	            roomNumber, guestName, guestEmail, guestCpf,
    56	            checkIn, checkOut, guests, ratePlan,
    57	            nights, subtotal, discount, total
    58	        );
    59	
    60	        return reservationRepository.save(reservation);
    61	    }
    62	
    63	    public Reservation getReservation(long reservationId) throws Exception {
    64	        return reservationRepository.findById(reservationId)
    65	            .orElseThrow(() -> new ApiException("RESERVATION_NOT_FOUND", "Reservation not found", 404));
    66	    }
    67	
    68	    public Reservation confirmReservation(long reservationId, double amountPaid) throws Exception {
    69	        Reservation reservation = getReservation(reservationId);
    70	
    71	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    72	            throw new ApiException("OPERATION_NOT_ALLOWED", "Only pending reservations can be confirmed", 409);
    73	        }
    74	
    75	        reservation.setStatus(ReservationStatus.CONFIRMED);
    76	        reservation.setAmountPaid(amountPaid);
    77	        reservationRepository.update(reservation);
    78	
    79	        // Send confirmation email
    80	        sendConfirmationEmail(reservation);
    81	
    82	        return reservation;
    83	    }
    84	
    85	    public Reservation checkInReservation(long reservationId) throws Exception {
    86	        Reservation reservation = getReservation(reservationId);
    87	
    88	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
    89	            throw new ApiException("OPERATION_NOT_ALLOWED", "Only confirmed reservations can check in", 409);
    90	        }
    91	
    92	        reservation.setStatus(ReservationStatus.CHECKED_IN);
    93	        reservationRepository.update(reservation);
    94	
    95	        return reservation;
    96	    }
    97	
    98	    public Reservation checkOutReservation(long reservationId) throws Exception {
    99	        Reservation reservation = getReservation(reservationId);
   100	
   101	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   102	            throw new ApiException("OPERATION_NOT_ALLOWED", "Only checked-in reservations can check out", 409);
   103	        }
   104	
   105	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
   106	        reservationRepository.update(reservation);
   107	
   108	        return reservation;
   109	    }
   110	
   111	    public Reservation cancelReservation(long reservationId) throws Exception {
   112	        Reservation reservation = getReservation(reservationId);
   113	
   114	        if (reservation.getStatus() != ReservationStatus.PENDING &&
   115	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
   116	            throw new ApiException("OPERATION_NOT_ALLOWED", "Only pending or confirmed reservations can be cancelled", 409);
   117	        }
   118	
   119	        reservation.setStatus(ReservationStatus.CANCELLED);
   120	
   121	        // Calculate refund
   122	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
   123	            reservation.setRefund(reservation.getAmountPaid());
   124	        } else {
   125	            reservation.setRefund(0.0);
   126	        }
   127	
   128	        reservationRepository.update(reservation);
   129	
   130	        return reservation;
   131	    }
   132	
   133	    private void sendConfirmationEmail(Reservation reservation) throws Exception {
   134	        String receipt = generateReceipt(reservation);
   135	        String body = String.format("""
   136	            Olá, %s!
   137	
   138	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
   139	
   140	            %s
   141	
   142	            A entrada é a partir das 14h, e a saída, até as 12h.
   143	            Até breve!
   144	            """, reservation.getGuestName(), receipt);
   145	
   146	        Message message = new Message(
   147	            MessageChannel.EMAIL,
   148	            reservation.getGuestEmail(),
   149	            "Reserva confirmada - Pousada Maré Alta",
   150	            body
   151	        );
   152	
   153	        messageRepository.save(message);
   154	    }
   155	
   156	    private String generateReceipt(Reservation reservation) throws Exception {
   157	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
   158	            .orElseThrow();
   159	
   160	        DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
   161	
   162	        String nightsText = reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias";
   163	
   164	        StringBuilder receipt = new StringBuilder();
   165	        receipt.append(String.format("Comprovante de reserva nº %d\n", reservation.getId()));
   166	        receipt.append(String.format("Hóspede: %s (CPF %s)\n", reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
   167	        receipt.append(String.format("Quarto: %d (%s)\n", reservation.getRoomNumber(), room.getType().getDisplayName()));
   168	        receipt.append(String.format("Entrada: %s | Saída: %s | %s\n",
   169	            reservation.getCheckIn().format(dateFormatter),
   170	            reservation.getCheckOut().format(dateFormatter),
   171	            nightsText));
   172	        receipt.append(String.format("Diárias: R$ %s\n", formatMoney(reservation.getSubtotal())));
   173	
   174	        if (reservation.getDiscount() > 0) {
   175	            receipt.append(String.format("Desconto: R$ %s\n", formatMoney(reservation.getDiscount())));
   176	        }
   177	
   178	        receipt.append(String.format("Total: R$ %s", formatMoney(reservation.getTotal())));
   179	
   180	        return receipt.toString();
   181	    }
   182	
   183	    private String formatCpf(String cpf) {
   184	        if (cpf.length() != 11) {
   185	            return cpf;
   186	        }
   187	        return String.format("%s.%s.%s-%s",
   188	            cpf.substring(0, 3),
   189	            cpf.substring(3, 6),
   190	            cpf.substring(6, 9),
   191	            cpf.substring(9, 11));
   192	    }
   193	
   194	    private String formatMoney(double value) {
   195	        String formatted = String.format("%.2f", value);
   196	        return formatted.replace(".", ",");
   197	    }
   198	
   199	    public String getReceiptDocument(long reservationId) throws Exception {
   200	        Reservation reservation = getReservation(reservationId);
   201	
   202	        if (reservation.getStatus() == ReservationStatus.PENDING || reservation.getStatus() == ReservationStatus.CANCELLED) {
   203	            throw new ApiException("OPERATION_NOT_ALLOWED", "Receipt is only available for paid reservations", 409);
   204	        }
   205	
   206	        return generateReceipt(reservation);
   207	    }
   208	}
