=== src/main/java/com/pousada/domain/SeasonCalculator.java
     1	package com.pousada.domain;
     2	
     3	import java.time.LocalDate;
     4	import java.time.Month;
     5	
     6	public class SeasonCalculator {
     7	    private static final double HIGH_SEASON_MULTIPLIER = 1.20;
     8	
     9	    public static boolean isHighSeason(LocalDate date) {
    10	        int month = date.getMonthValue();
    11	        int day = date.getDayOfMonth();
    12	
    13	        if ((month == 12 && day >= 15) || month == 1 || month == 2) {
    14	            return true;
    15	        }
    16	        if (month == 7) {
    17	            return true;
    18	        }
    19	        return false;
    20	    }
    21	
    22	    public static double calculateNightlyRate(double baseRate, LocalDate date) {
    23	        if (isHighSeason(date)) {
    24	            return Rounding.round(baseRate * HIGH_SEASON_MULTIPLIER);
    25	        }
    26	        return Rounding.round(baseRate);
    27	    }
    28	
    29	    public static double calculateSubtotal(double baseRate, LocalDate checkIn, LocalDate checkOut) {
    30	        double subtotal = 0.0;
    31	        LocalDate current = checkIn;
    32	
    33	        while (current.isBefore(checkOut)) {
    34	            subtotal += calculateNightlyRate(baseRate, current);
    35	            current = current.plusDays(1);
    36	        }
    37	
    38	        return Rounding.round(subtotal);
    39	    }
    40	}

