    12	    public static Connection getConnection() throws Exception {
    13	        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    14	    }
    15	
    16	    public static void initialize() {
    17	        try (Connection conn = getConnection();
    18	             Statement stmt = conn.createStatement()) {
    19	
    20	            // Create rooms table
    21	            stmt.execute("""
    22	                CREATE TABLE IF NOT EXISTS rooms (
    23	                    number INT PRIMARY KEY,
    24	                    type VARCHAR(20) NOT NULL
    25	                )
    26	            """);
    27	
    28	            // Create reservations table
    29	            stmt.execute("""
    30	                CREATE TABLE IF NOT EXISTS reservations (
    31	                    id BIGSERIAL PRIMARY KEY,
    32	                    room_number INT NOT NULL,
    33	                    guest_name VARCHAR(255) NOT NULL,
    34	                    guest_email VARCHAR(255) NOT NULL,
    35	                    guest_cpf VARCHAR(20) NOT NULL,
    36	                    check_in DATE NOT NULL,
    37	                    check_out DATE NOT NULL,
    38	                    guests INT NOT NULL,
    39	                    rate_plan VARCHAR(50) NOT NULL,
    40	                    nights INT NOT NULL,
    41	                    subtotal NUMERIC(10, 2) NOT NULL,
    42	                    discount NUMERIC(10, 2) NOT NULL,
    43	                    total NUMERIC(10, 2) NOT NULL,
    44	                    status VARCHAR(50) NOT NULL,
    45	                    amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
    46	                    refund NUMERIC(10, 2),
    47	                    FOREIGN KEY (room_number) REFERENCES rooms(number)
    48	                )
    49	            """);
    50	
    51	            // Create messages table
    52	            stmt.execute("""
    53	                CREATE TABLE IF NOT EXISTS messages (
    54	                    id BIGSERIAL PRIMARY KEY,
    55	                    channel VARCHAR(50) NOT NULL,
    56	                    recipient VARCHAR(255) NOT NULL,
    57	                    subject VARCHAR(255) NOT NULL,
    58	                    body TEXT NOT NULL
    59	                )
    60	            """);
    61	
    62	            // Insert rooms
    63	            stmt.execute("DELETE FROM rooms");
    64	            stmt.execute("INSERT INTO rooms (number, type) VALUES (101, 'STANDARD')");
    65	            stmt.execute("INSERT INTO rooms (number, type) VALUES (102, 'STANDARD')");
    66	            stmt.execute("INSERT INTO rooms (number, type) VALUES (201, 'DELUXE')");
    67	            stmt.execute("INSERT INTO rooms (number, type) VALUES (202, 'DELUXE')");
    68	            stmt.execute("INSERT INTO rooms (number, type) VALUES (301, 'SUITE')");
    69	
    70	            conn.commit();
    71	        } catch (Exception e) {
    72	            throw new RuntimeException("Failed to initialize database", e);
    73	        }
    74	    }
